            scenes.add(new NaturalScene("fox_" + biome, EntityTypes.FOX, biome, 2, 15, 0, 0, false, -32, 0, 289, true, false));
            scenes.add(new NaturalScene("wolf_" + biome, EntityTypes.WOLF, biome, 2, 15, 0, 0, false, -32, 0, 289, true, false));
