    @SuppressWarnings("unchecked")
    /** 测试夹具：把 `Bee.DATA_FLAGS_ID` 的已蜇位打开。 */
    private static void setBeeStung(net.minecraft.world.entity.animal.bee.Bee bee, boolean value)
            throws Exception {
        var field = net.minecraft.world.entity.animal.bee.Bee.class.getDeclaredField("DATA_FLAGS_ID");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        var accessor = (net.minecraft.network.syncher.EntityDataAccessor<Byte>) field.get(null);
        byte flags = bee.getEntityData().get(accessor);
        bee.getEntityData().set(accessor, (byte) (value ? flags | 4 : flags & ~4));
    }

    /** 测试夹具：把 `Bee.DATA_FLAGS_ID` 的花蜜位打开。 */
    private static void setBeeNectar(net.minecraft.world.entity.animal.bee.Bee bee, boolean value)
            throws Exception {
        var field = net.minecraft.world.entity.animal.bee.Bee.class.getDeclaredField("DATA_FLAGS_ID");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        var accessor = (net.minecraft.network.syncher.EntityDataAccessor<Byte>) field.get(null);
        byte flags = bee.getEntityData().get(accessor);
        bee.getEntityData().set(accessor, (byte) (value ? flags | 8 : flags & ~8));
    }

    private static <T> T allocate(Class<T> type) {
        try {
            return (T) UNSAFE.allocateInstance(type);
        } catch (InstantiationException error) {
            throw new IllegalStateException(error);
        }
    }

    private static Unsafe loadUnsafe() {
        try {
            Field field = Unsafe.class.getDeclaredField("theUnsafe");
            field.setAccessible(true);
            return (Unsafe) field.get(null);
        } catch (ReflectiveOperationException error) {
            throw new IllegalStateException(error);
        }
    }

    private static float getFloat(Class<?> owner, Object target, String name) {
        try {
            Field field = owner.getDeclaredField(name);
            field.setAccessible(true);
            return field.getFloat(target);
        } catch (ReflectiveOperationException error) {
            throw new IllegalStateException(error);
        }
    }

    private static void putFloat(Class<?> owner, Object target, String name, float value) {
        try {
            Field field = owner.getDeclaredField(name);
            requireFieldType(field, float.class);
            UNSAFE.putFloat(target, UNSAFE.objectFieldOffset(field), value);
        } catch (ReflectiveOperationException error) {
            throw new IllegalStateException(error);
        }
    }

    private static void putBoolean(Class<?> owner, Object target, String name, boolean value) {
        try {
            Field field = owner.getDeclaredField(name);
            requireFieldType(field, boolean.class);
            UNSAFE.putBoolean(target, UNSAFE.objectFieldOffset(field), value);
        } catch (ReflectiveOperationException error) {
            throw new IllegalStateException(error);
        }
    }

    private static void put(Class<?> owner, Object target, String name, Object value) {
        try {
            Field field = owner.getDeclaredField(name);
            Class<?> type = field.getType();
            long offset = UNSAFE.objectFieldOffset(field);
            // 基本类型字段按自己的宽度写；传进来的必须是对应的包装类。
            // Primitive fields are written at their own width; the value must be the matching box.
            if (type == int.class && value instanceof Integer number) {
                UNSAFE.putInt(target, offset, number);
            } else if (type == boolean.class && value instanceof Boolean flag) {
                UNSAFE.putBoolean(target, offset, flag);
            } else if (type == float.class && value instanceof Float number) {
                UNSAFE.putFloat(target, offset, number);
            } else if (type == double.class && value instanceof Double number) {
                UNSAFE.putDouble(target, offset, number);
            } else if (type == long.class && value instanceof Long number) {
                UNSAFE.putLong(target, offset, number);
            } else if (type == short.class && value instanceof Short number) {
                UNSAFE.putShort(target, offset, number);
            } else if (type == byte.class && value instanceof Byte number) {
                UNSAFE.putByte(target, offset, number);
            } else if (!type.isPrimitive() && (value == null || type.isInstance(value))) {
                UNSAFE.putObject(target, offset, value);
            } else {
                throw new IllegalStateException("put " + owner.getName() + "." + name + ": field is "
                        + type.getName() + ", value is "
                        + (value == null ? "null" : value.getClass().getName()));
            }
        } catch (ReflectiveOperationException error) {
            throw new IllegalStateException(error);
        }
    }

    /** 官方 `findRespawnPositionAndUseSpawnBlock` 在假世界里会去问
     * `MinecraftServer.getWorldData()`；Bamboo 的出生点是 `LevelData.RespawnData.DEFAULT`，
     * 这里直接按同样坐标造一个 `TeleportTransition`。 */
    private static final class LifePlayer extends ServerPlayer {
        private final FakeLevel level;

        LifePlayer(net.minecraft.server.MinecraftServer server, FakeLevel level,
                GameProfile profile, ClientInformation info, FakeLevel same) {
            super(server, level, profile, info);
            this.level = same;
        }

        @Override
        public net.minecraft.world.level.portal.TeleportTransition findRespawnPositionAndUseSpawnBlock(
                boolean conqueredEnd,
                net.minecraft.world.level.portal.TeleportTransition.PostTeleportTransition post) {
            var data = level.getRespawnData();
            var pos = data.pos();
            return new net.minecraft.world.level.portal.TeleportTransition(level,
                    // Bamboo 的超平坦地表：和 `flat::surface_y()` 一致。
                    new Vec3(pos.getX() + 0.5, -60.0, pos.getZ() + 0.5),
                    Vec3.ZERO, data.yaw(), data.pitch(), post);
        }
    }

    /** 只记 `connection.send` 的包：玩家自己收到的 `set_health` / `hurt_animation`。 */
    private static final class RecordingListener extends ServerGamePacketListenerImpl {
        private RecordingListener() {
            super(null, null, null, null);
        }

        Bytes bytes;

        @Override
        public void send(net.minecraft.network.protocol.Packet<?> packet) {
            @SuppressWarnings("unchecked")
            net.minecraft.network.protocol.Packet<? super net.minecraft.network.protocol.game.ClientGamePacketListener> cast =
                    (net.minecraft.network.protocol.Packet<? super net.minecraft.network.protocol.game.ClientGamePacketListener>) packet;
            bytes.add(cast);
        }

        @Override
        public void send(net.minecraft.network.protocol.Packet<?> packet,
                io.netty.channel.ChannelFutureListener listener) {
            send(packet);
        }

        @Override
        public void teleport(double x, double y, double z, float yaw, float pitch) {
            // `PlayerList.respawn` 里的 `connection.teleport` 会发 player_position，
            // 这里按官方 `ServerGamePacketListenerImpl.teleport` 的字节记下来。
            send(net.minecraft.network.protocol.game.ClientboundPlayerPositionPacket.of(
                    1, new net.minecraft.world.entity.PositionMoveRotation(
                            new Vec3(x, y, z), Vec3.ZERO, yaw, pitch),
                    java.util.Collections.emptySet()));
        }

        @Override
        public boolean hasClientLoaded() {
            return true;
        }

        @Override
        public boolean isAcceptingMessages() {
            // 假连接没有 Netty 通道，按「已连上」处理，末影珍珠才会真的传送主人。
            return true;
        }

        @Override
        public void markClientUnloadedAfterDeath() {}
    }

    private static final class StubList extends DedicatedPlayerList {
        private StubList() {
            super(null, null, null);
        }

        @Override
        public ServerStatsCounter getPlayerStats(Player player) {
            return stats;
        }

        @Override
        public PlayerAdvancements getPlayerAdvancements(ServerPlayer player) {
            return advancements;
        }

        /** 环境音：把官方的音效包也记进同一刻的字节流。 */
        java.util.function.Consumer<Packet<? super ClientGamePacketListener>> sounds;
        /** 1b：死者自己的链路和系统消息广播的收集器。 */
        Bytes lifeSelf;
        Bytes lifeBroadcast;

        @Override
        public java.util.List<ServerPlayer> getPlayers() {
            return java.util.List.of();
        }

        @Override
        public int getPlayerCount() {
            return 0;
        }

        @Override
        public void broadcastSystemMessage(Component message, boolean overlay) {
            // 官方广播给所有玩家；假世界只有一名玩家，记一次 system_chat。
            if (lifeBroadcast != null) {
                lifeBroadcast.add(new ClientboundSystemChatPacket(message, overlay));
            }
        }

        @Override
        public void sendLevelInfo(ServerPlayer player, ServerLevel level) {
            // 官方 `PlayerList.sendLevelInfo` 的包顺序；假世界时钟是 0，
            // 天晴。`set_time` 用官方 codec 的空时钟同步包。
            var connection = player.connection;
            var border = level.getWorldBorder();
            connection.send(new net.minecraft.network.protocol.game.ClientboundInitializeBorderPacket(border));
            connection.send(new net.minecraft.network.protocol.game.ClientboundSetTimePacket(
                    level.getGameTime(), java.util.Map.of()));
            connection.send(new ClientboundSetDefaultSpawnPositionPacket(level.getRespawnData()));
            connection.send(new net.minecraft.network.protocol.game.ClientboundGameEventPacket(
                    net.minecraft.network.protocol.game.ClientboundGameEventPacket.LEVEL_CHUNKS_LOAD_START,
                    0.0F));
            if (lifeSelf != null) {
                // `PlayerList.sendAllPlayerInfo` 的 initInventoryMenu 部分：
                // 权限事件、命令树、配对元数据、装备、整套物品栏、手持槽、能力。
                connection.send(new net.minecraft.network.protocol.game.ClientboundEntityEventPacket(
                        player, (byte) 26));
                var data = player.getEntityData();
                connection.send(new net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket(
                        player.getId(), data.packDirty()));
                var slots = new java.util.ArrayList<com.mojang.datafixers.util.Pair<
                        net.minecraft.world.entity.EquipmentSlot, ItemStack>>();
                for (var slot : net.minecraft.world.entity.EquipmentSlot.values()) {
                    if (slot == net.minecraft.world.entity.EquipmentSlot.BODY
                            || slot == net.minecraft.world.entity.EquipmentSlot.SADDLE) continue;
                    slots.add(com.mojang.datafixers.util.Pair.of(slot, player.getItemBySlot(slot)));
                }
                connection.send(new net.minecraft.network.protocol.game.ClientboundSetEquipmentPacket(
                        player.getId(), slots));
                var items = new java.util.ArrayList<ItemStack>();
                for (int i = 0; i < 46; i++) items.add(ItemStack.EMPTY);
                for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
                    items.set(i, player.getInventory().getItem(i));
                }
                connection.send(new net.minecraft.network.protocol.game.ClientboundContainerSetContentPacket(
                        0, 0, items, ItemStack.EMPTY));
                connection.send(new net.minecraft.network.protocol.game.ClientboundSetHeldSlotPacket(
                        player.getInventory().getSelectedSlot()));
                connection.send(new net.minecraft.network.protocol.game.ClientboundPlayerAbilitiesPacket(
                        player.getAbilities()));
            }
        }

        @Override
        public void sendPlayerPermissionLevel(ServerPlayer player) {
            // 假世界没有 OP 名单，权限用 GAMEMASTERS，命令树留给 Bamboo 的
            // `send_session` 按自己的权限等级生成；这里只记 entity_event。
            if (lifeSelf != null) {
                lifeSelf.add(new net.minecraft.network.protocol.game.ClientboundEntityEventPacket(
                        player, (byte) 26));
            }
        }

        @Override
        public void broadcast(Player except, double x, double y, double z, double range,
                net.minecraft.resources.ResourceKey<Level> dimension, Packet<?> packet) {
            if (sounds != null) {
                @SuppressWarnings("unchecked")
                Packet<? super ClientGamePacketListener> cast =
                        (Packet<? super ClientGamePacketListener>) packet;
                sounds.accept(cast);
            }
        }
    }

    /** 闪电自己对拍：构造、逐刻的 life / flashes / 实体随机源，以及第一刻引火后场景方块。 */
    private static int playLightning(Official official, Writer out, String only) throws Exception {
        int cases = 0;
        List<String> names = List.of("lightning_fire", "lightning_visual", "lightning_copper",
                "lightning_rod", "trap_near", "trap_far");
        for (String name : names) {
            if (only != null && !name.startsWith(only)) continue;
            boolean trap = name.startsWith("trap");
            FakeLevel level = FakeLevel.create(official);
            ((TickingLevelData) level.levelData).difficulty = Difficulty.NORMAL;
            level.nextId = FIRST_ID;
            level.entitySeeds = RandomSource.create(ENTITY_RANDOM_SEED);
            level.spawned = new ArrayList<>();
            level.tracked = new ArrayList<>();
            Long2ObjectOpenHashMap<BlockState> blocks = new Long2ObjectOpenHashMap<>();
            // 落点在 (0.5, 64, 0.5)。草地给火一个落脚点；铜场景放一块生锈的铜。
            for (int x = -2; x <= 2; x++) {
                for (int z = -2; z <= 2; z++) {
                    blocks.put(BlockPos.asLong(x, 63, z), Blocks.GRASS_BLOCK.defaultBlockState());
                }
            }
            if (name.equals("lightning_rod")) {
                blocks.put(BlockPos.asLong(0, 64, 0), Blocks.LIGHTNING_ROD.weathering().unaffected().defaultBlockState());
            }
            if (name.equals("lightning_copper")) {
                blocks.put(BlockPos.asLong(0, 63, 0), Blocks.COPPER_BLOCK.weathering().oxidized().defaultBlockState());
            }
            level.blocks.putAll(blocks);
            long[] keys = blocks.keySet().toLongArray();
            Arrays.sort(keys);
            StringBuilder blockJson = new StringBuilder("[");
            for (int i = 0; i < keys.length; i++) {
                if (i > 0) blockJson.append(',');
                BlockPos pos = BlockPos.of(keys[i]);
                blockJson.append('[').append(pos.getX()).append(',').append(pos.getY()).append(',')
                        .append(pos.getZ()).append(',').append(Block.getId(blocks.get(keys[i]))).append(']');
            }
            blockJson.append(']');
            int ticks = 40;
            Entity subject;
            if (trap) {
                net.minecraft.world.entity.animal.equine.SkeletonHorse horse =
                        EntityTypes.SKELETON_HORSE.create(level, EntitySpawnReason.EVENT);
                horse.setTrap(true);
                horse.setAge(0);
                horse.snapTo(0.5, 64.0, 0.5, 0.0F, 0.0F);
                level.entitySeeds.nextLong();
                setRandom(horse, 7L);
                horse.setUUID(new UUID(0L, 1L));
                horse.setId(FIRST_ID);
                level.tracked.add(horse);
                subject = horse;
            } else {
                net.minecraft.world.entity.LightningBolt bolt =
                        EntityTypes.LIGHTNING_BOLT.create(level, EntitySpawnReason.EVENT);
                bolt.setVisualOnly(name.equals("lightning_visual"));
                bolt.snapTo(0.5, 64.0, 0.5);
                level.entitySeeds.nextLong();
                setRandom(bolt, 7L);
                RandomSource random = bolt.getRandom();
                random.nextLong();
                random.nextInt(3);
                put(net.minecraft.world.entity.LightningBolt.class, bolt, "seed", Long.valueOf(0L));
                putInt(net.minecraft.world.entity.LightningBolt.class, bolt, "flashes", 1);
                putInt(net.minecraft.world.entity.LightningBolt.class, bolt, "life", 2);
                bolt.setId(FIRST_ID);
                level.tracked.add(bolt);
                subject = bolt;
            }
            StringBuilder frames = new StringBuilder("[");
            for (int tick = 0; tick <= ticks; tick++) {
                if (tick > 0) {
                    if (name.equals("trap_near") && tick == 4) {
                        ServerPlayer player = new ServerPlayer(official.server, level,
                                new GameProfile(new UUID(1L, 2L), "TrapOracle"), ClientInformation.createDefault());
                        player.setId(FIRST_ID + 2);
                        player.setPos(2.5, 64.0, 0.5);
                        setRandom(player, ENTITY_RANDOM_SEED);
                        level.playersList().add(player);
                        level.tracked.add(player);
                    }
                    for (Entity entity : new ArrayList<>(level.tracked)) {
                        if (entity.isRemoved() || entity instanceof ServerPlayer) continue;
                        entity.commonTick();
                        entity.tick();
                    }
                    for (Entity born : level.spawned) {
                        if (!(born instanceof net.minecraft.world.entity.animal.equine.SkeletonHorse)
                                && !(born instanceof net.minecraft.world.entity.monster.skeleton.Skeleton)
                                && !(born instanceof net.minecraft.world.entity.LightningBolt)) continue;
                        if (!level.tracked.contains(born)) level.tracked.add(born);
                        setRandom(born, level.entitySeeds.nextLong());
                    }
                    level.spawned.clear();
                }
                if (tick > 0) frames.append(',');
                if (trap) {
                    var horse = (net.minecraft.world.entity.animal.equine.SkeletonHorse) subject;
                    long bolts = level.tracked.stream().filter(
                            e -> e instanceof net.minecraft.world.entity.LightningBolt).count();
                    frames.append('[').append(horse.isTrap() ? 1 : 0).append(',')
                            .append(horse.isTamed() ? 1 : 0).append(',')
                            .append(randomSeed(subject)).append(',')
                            .append(level.tracked.size()).append(',').append(bolts).append(',')
                            .append(randomSeed(level.getRandom())).append(']');
                } else {
                    var bolt = (net.minecraft.world.entity.LightningBolt) subject;
                    int life = (int) getInt(net.minecraft.world.entity.LightningBolt.class, bolt, "life");
                    int flashes = (int) getInt(net.minecraft.world.entity.LightningBolt.class, bolt, "flashes");
                    frames.append('[').append(life).append(',').append(flashes).append(',')
                            .append(randomSeed(subject)).append(',')
                            .append(randomSeed(level.getRandom())).append(",0]");
                }
            }
            frames.append(']');
            StringBuilder finalBlocks = new StringBuilder("[");
            for (int i = 0; i < keys.length; i++) {
                if (i > 0) finalBlocks.append(',');
                finalBlocks.append(Block.getId(level.getBlockState(BlockPos.of(keys[i]))));
            }
            finalBlocks.append(']');
            if (trap) {
                out.write("{\"type\":\"skeletonTrap\",\"name\":" + jsonString(name)
                        + ",\"firstId\":" + FIRST_ID + ",\"start\":[0.5,64.0,0.5],\"player\":"
                        + (name.equals("trap_near") ? "[2.5,64.0,0.5]" : "null")
                        + ",\"playerTick\":4,\"frames\":" + frames + "}\n");
            } else {
                out.write("{\"type\":\"lightning\",\"name\":" + jsonString(name)
                        + ",\"firstId\":" + FIRST_ID + ",\"seed\":7,\"start\":[0.5,64.0,0.5],\"visual\":"
                        + name.equals("lightning_visual") + ",\"blocks\":" + blockJson
                        + ",\"frames\":" + frames + ",\"finalBlocks\":" + finalBlocks + "}\n");
            }
            cases++;
        }
        return cases;
    }

    /** 陷阱骑士的装备与附魔：`createSkeleton` 的 `finalizeSpawn` + 两次 provider。
     *  用四个固定种子显式建骷髅（官方 `EntityType.create` 的随机源不带种子，
     *  夹具按岛种子源替换），再按 `createSkeleton` 的顺序调官方方法，逐位比装备。 */
    private static int playTrapGear(Official official, Writer out) throws Exception {
        int cases = 0;
        Method enchantMethod = net.minecraft.world.entity.animal.equine.SkeletonTrapGoal.class
                .getDeclaredMethod("enchant",
                        net.minecraft.world.entity.monster.skeleton.Skeleton.class,
                        net.minecraft.world.entity.EquipmentSlot.class,
                        net.minecraft.world.DifficultyInstance.class);
        enchantMethod.setAccessible(true);
        var goal = allocate(net.minecraft.world.entity.animal.equine.SkeletonTrapGoal.class);
        var difficulty = new DifficultyInstance(Difficulty.NORMAL, 0L, 0L, 0.0F);
        for (long seed : new long[] {1L, 7L, 42L, 12345L}) {
            FakeLevel level = FakeLevel.create(official);
            ((TickingLevelData) level.levelData).difficulty = Difficulty.NORMAL;
            level.nextId = FIRST_ID;
            level.entitySeeds = RandomSource.create(ENTITY_RANDOM_SEED);
            level.spawned = new ArrayList<>();
            level.tracked = new ArrayList<>();
            level.getRandom().setSeed(seed);
            level.spawnDifficulty = difficulty;
            StringBuilder seedsJson = new StringBuilder("[");
            StringBuilder gear = new StringBuilder("[");
            for (int i = 0; i < 4; i++) {
                // 官方 `EntityType.create`：构造后立刻换成确定种子，再跑 `finalizeSpawn`。
                var knight = (net.minecraft.world.entity.monster.skeleton.Skeleton)
                        EntityTypes.SKELETON.create(level, EntitySpawnReason.TRIGGERED);
                long entitySeed = level.entitySeeds.nextLong();
                setRandom(knight, entitySeed);
                if (i > 0) { seedsJson.append(','); gear.append(','); }
                seedsJson.append(seedOf(knight));
                knight.finalizeSpawn(level, difficulty, EntitySpawnReason.TRIGGERED, null);
                knight.setInvulnerableTime(60);
                knight.setPersistenceRequired();
                if (knight.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.HEAD).isEmpty()) {
                    knight.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,
                            new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.IRON_HELMET));
                }
                for (var slot : new net.minecraft.world.entity.EquipmentSlot[] {
                        net.minecraft.world.entity.EquipmentSlot.MAINHAND,
                        net.minecraft.world.entity.EquipmentSlot.HEAD }) {
                    enchantMethod.invoke(goal, knight, slot, difficulty);
                }
                gear.append('[');
                for (var slot : new net.minecraft.world.entity.EquipmentSlot[] {
                        net.minecraft.world.entity.EquipmentSlot.MAINHAND,
                        net.minecraft.world.entity.EquipmentSlot.FEET,
                        net.minecraft.world.entity.EquipmentSlot.LEGS,
                        net.minecraft.world.entity.EquipmentSlot.CHEST,
                        net.minecraft.world.entity.EquipmentSlot.HEAD }) {
                    var stack = knight.getItemBySlot(slot);
                    var enchants = stack.getOrDefault(
                            net.minecraft.core.component.DataComponents.ENCHANTMENTS,
                            net.minecraft.world.item.enchantment.ItemEnchantments.EMPTY);
                    var levels = new java.util.ArrayList<String>();
                    enchants.entrySet().forEach(entry -> levels.add(
                            entry.getKey().getRegisteredName() + "@" + entry.getIntValue()));
                    levels.sort(String::compareTo);
                    gear.append(jsonString(BuiltInRegistries.ITEM.getId(stack.getItem())
                            + ":{" + String.join(",", levels) + "}")).append(',');
                }
                gear.append(jsonString(knight.isLeftHanded() ? "1" : "0")).append(']');
            }
            out.write("{\"type\":\"trapGear\",\"name\":\"trap_gear_" + seed + "\""
                    + ",\"seed\":" + seed + ",\"seeds\":" + seedsJson.append(']')
                    + ",\"gear\":" + gear.append(']') + "}\n");
            cases++;
        }
        return cases;
    }

    /** 骷髅马 / 僵尸马的逐刻、存档和死亡掉落。 */
    private static int playUndeadHorse(Official official, Writer out, String only) throws Exception {
        int cases = 0;
        boolean all = only == null || only.equals("undead_horse");
        if (all || only.startsWith("undead_horse_tick")) {
            cases += playUndeadHorseTick(official, out);
        }
        if (all || only.startsWith("undead_horse_save")) {
            cases += playUndeadHorseSave(official, out);
        }
        if (all || only.startsWith("undead_horse_death")) {
            cases += playUndeadHorseDeath(official, out);
        }
        return cases;
    }

    private static net.minecraft.world.entity.animal.equine.AbstractHorse undeadHorse(
            FakeLevel level, boolean skeleton, long seed) {
        var horse = (net.minecraft.world.entity.animal.equine.AbstractHorse)
                (skeleton ? EntityTypes.SKELETON_HORSE : EntityTypes.ZOMBIE_HORSE)
                        .create(level, EntitySpawnReason.COMMAND);
        setRandom(horse, seed);
        horse.setUUID(new UUID(0L, 1L));
        horse.setId(FIRST_ID);
        horse.snapTo(0.5, 64.0, 0.5, 0.0F, 0.0F);
        horse.setNoAi(true);
        level.tracked.add(horse);
        return horse;
    }

    private static int playUndeadHorseTick(Official official, Writer out) throws Exception {
        int cases = 0;
        for (boolean skeleton : new boolean[] {true, false}) {
            for (int variant = 0; variant < 3; variant++) {
                FakeLevel level = FakeLevel.create(official);
                ((TickingLevelData) level.levelData).difficulty = Difficulty.NORMAL;
                level.nextId = FIRST_ID;
                level.entitySeeds = RandomSource.create(ENTITY_RANDOM_SEED);
                level.spawned = new ArrayList<>();
                level.tracked = new ArrayList<>();
                boolean water = variant == 0;
                boolean tamed = variant == 1;
                boolean player = variant == 2;
                for (int x = -2; x <= 2; x++) {
                    for (int z = -2; z <= 2; z++) {
                        if (water) {
                            level.blocks.put(BlockPos.asLong(x, 63, z), Blocks.STONE.defaultBlockState());
                            for (int y = 64; y <= 66; y++) {
                                level.blocks.put(BlockPos.asLong(x, y, z), Blocks.WATER.defaultBlockState());
                            }
                        } else {
                            level.blocks.put(BlockPos.asLong(x, 63, z), Blocks.GRASS_BLOCK.defaultBlockState());
                        }
                    }
                }
                long[] keys = level.blocks.keySet().toLongArray();
                Arrays.sort(keys);
                StringBuilder blockJson = new StringBuilder("[");
                for (int i = 0; i < keys.length; i++) {
                    if (i > 0) blockJson.append(',');
                    BlockPos pos = BlockPos.of(keys[i]);
                    blockJson.append('[').append(pos.getX()).append(',').append(pos.getY()).append(',')
                            .append(pos.getZ()).append(',').append(Block.getId(level.blocks.get(keys[i]))).append(']');
                }
                blockJson.append(']');
                var horse = undeadHorse(level, skeleton, 7L);
                if (tamed) horse.setTamed(true);
                // 交互拒绝场景用幼年马：`AbstractHorse.mobInteract` 早退到
                // `Animal.mobInteract`（空手 PASS），不会走 `doPlayerRide` 需要连接的那支。
                if (player) horse.setAge(-24000);
                ServerPlayer actor = null;
                if (player) {
                    actor = new ServerPlayer(official.server, level,
                            new GameProfile(new UUID(1L, 2L), "HorseOracle"), ClientInformation.createDefault());
                    actor.setId(FIRST_ID + 8);
                    actor.setPos(2.5, 64.0, 0.5);
                    level.playersList().add(actor);
                    // 假玩家不进 tracked，免得它自己也 tick。
                }
                StringBuilder frames = new StringBuilder("[");
                for (int tick = 0; tick <= 6; tick++) {
                    if (tick > 0) {
                        horse.commonTick();
                        horse.tick();
                    }
                    if (tick > 0) frames.append(',');
                    int interaction = 0;
                    if (player) {
                        var result = horse.mobInteract(actor, InteractionHand.MAIN_HAND);
                        interaction = switch (result.getClass().getSimpleName()) {
                            case "Pass" -> 0;
                            case "Success" -> 1;
                            case "SuccessServer" -> 2;
                            case "Consume" -> 3;
                            case "Fail" -> 4;
                            default -> 5;
                        };
                    }
                    boolean trap = skeleton
                            && ((net.minecraft.world.entity.animal.equine.SkeletonHorse) horse).isTrap();
                    frames.append('[').append(Float.floatToRawIntBits(horse.getHealth())).append(',')
                            .append(horse.getAirSupply()).append(',')
                            .append(horse.getRemainingFireTicks()).append(',')
                            .append(horse.isTamed() ? 1 : 0).append(',')
                            .append(trap ? 1 : 0).append(',')
                            .append(interaction).append(',')
                            .append(levelSeed(level)).append(']');
                }
                frames.append(']');
                String name = "undead_horse_tick_" + (skeleton ? "skeleton" : "zombie") + "_" + variant;
                out.write("{\"type\":\"undeadHorse\",\"name\":" + jsonString(name)
                        + ",\"firstId\":" + FIRST_ID + ",\"seed\":7,\"skeleton\":" + skeleton
                        + ",\"blocks\":" + blockJson + ",\"tamed\":" + tamed
                        + ",\"player\":" + player + ",\"frames\":" + frames + "}\n");
                cases++;
            }
        }
        return cases;
    }

    private static int playUndeadHorseSave(Official official, Writer out) throws Exception {
        int cases = 0;
        for (boolean skeleton : new boolean[] {true, false}) {
            for (boolean trap : new boolean[] {false, true}) {
                FakeLevel world = FakeLevel.create(official);
                var horse = undeadHorse(world, skeleton, 7L);
                horse.setTamed(true);
                horse.setAge(-24000);
                if (skeleton && trap) {
                    ((net.minecraft.world.entity.animal.equine.SkeletonHorse) horse).setTrap(true);
                }
                var output = net.minecraft.world.level.storage.TagValueOutput.createWithContext(
                        net.minecraft.util.ProblemReporter.DISCARDING, official.registries);
                horse.saveWithoutId(output);
                var copy = (net.minecraft.world.entity.animal.equine.AbstractHorse)
                        (skeleton ? EntityTypes.SKELETON_HORSE : EntityTypes.ZOMBIE_HORSE)
                                .create(world, EntitySpawnReason.LOAD);
                copy.load(net.minecraft.world.level.storage.TagValueInput.create(
                        net.minecraft.util.ProblemReporter.DISCARDING, official.registries, output.buildResult()));
                var again = net.minecraft.world.level.storage.TagValueOutput.createWithContext(
                        net.minecraft.util.ProblemReporter.DISCARDING, official.registries);
                copy.saveWithoutId(again);
                String name = "undead_horse_save_" + (skeleton ? "skeleton" : "zombie") + "_" + trap;
                out.write("{\"type\":\"undeadHorseSave\",\"name\":" + jsonString(name)
                        + ",\"skeleton\":" + skeleton + ",\"nbt\":" + jsonString(output.buildResult().toString())
                        + ",\"reloaded\":" + jsonString(again.buildResult().toString()) + "}\n");
                cases++;
            }
        }
        return cases;
    }

    private static int playUndeadHorseDeath(Official official, Writer out) throws Exception {
        int cases = 0;
        for (boolean skeleton : new boolean[] {true, false}) {
            for (boolean byPlayer : new boolean[] {true, false}) {
                official.server.sequences = new RandomSequences();
                FakeLevel world = FakeLevel.create(official);
                ((TickingLevelData) world.levelData).difficulty = Difficulty.NORMAL;
                world.spawned = new ArrayList<>();
                world.tracked = new ArrayList<>();
                var horse = undeadHorse(world, skeleton, 7L);
                ServerPlayer player = null;
                if (byPlayer) {
                    player = new ServerPlayer(official.server, world,
                            new GameProfile(new UUID(1L, 2L), "HorseDeath"), ClientInformation.createDefault());
                    player.setId(FIRST_ID + 8);
                    player.setPos(2.5, 64.0, 0.5);
                    world.playersList().add(player);
                }
                DamageSource source = byPlayer ? world.damageSources().playerAttack(player)
                        : world.damageSources().generic();
                horse.hurtServer(world, source, 100.0F);
                for (int tick = 0; tick < 25; tick++) {
                    world.gameTime++;
                    if (!horse.isRemoved()) {
                        horse.commonTick();
                        horse.tick();
                    }
                }
                List<String> items = new ArrayList<>();
                for (Entity entity : world.spawned) {
                    if (entity instanceof net.minecraft.world.entity.item.ItemEntity item && !item.getItem().isEmpty()) {
                        items.add(BuiltInRegistries.ITEM.getKey(item.getItem().getItem()) + "x" + item.getItem().getCount());
                    }
                }
                items.sort(String::compareTo);
                String name = "undead_horse_death_" + (skeleton ? "skeleton" : "zombie") + "_" + byPlayer;
                out.write("{\"type\":\"undeadHorseDeath\",\"name\":" + jsonString(name)
                        + ",\"skeleton\":" + skeleton + ",\"byPlayer\":" + byPlayer
                        + ",\"removed\":" + horse.isRemoved()
                        + ",\"items\":" + items.stream().map(MobOracle::jsonString)
                                .collect(java.util.stream.Collectors.joining(",", "[", "]")) + "}\n");
                cases++;
            }
        }
        return cases;
    }

    /** 雷击落点（多活物的实体分区顺序）与 `thunderHit` 的逐刻对拍。 */
    private static int playThunder(Official official, Writer out, String only) throws Exception {
        int cases = 0;
        if (only == null || only.startsWith("thunder_target")) {
            cases += playThunderTarget(official, out);
        }
        if (only == null || only.startsWith("thunder_hit")) {
            cases += playThunderHit(official, out, only);
        }
        return cases;
    }

    /** `findLightningTargetAround` 的活物列表顺序：四头牛在三个不同实体段里。 */
    private static int playThunderTarget(Official official, Writer out) throws Exception {
        FakeLevel level = FakeLevel.create(official);
        ((TickingLevelData) level.levelData).difficulty = Difficulty.NORMAL;
        level.nextId = FIRST_ID;
        level.entitySeeds = RandomSource.create(ENTITY_RANDOM_SEED);
        level.spawned = new ArrayList<>();
        level.tracked = new ArrayList<>();
        level.injectedCanSeeSky = true;
        level.getRandom().setSeed(1L);
        for (int x = -8; x <= 24; x++) {
            for (int z = -8; z <= 8; z++) {
                level.blocks.put(BlockPos.asLong(x, 63, z), Blocks.GRASS_BLOCK.defaultBlockState());
            }
        }
        long[] keys = level.blocks.keySet().toLongArray();
        Arrays.sort(keys);
        StringBuilder blockJson = new StringBuilder("[");
        for (int i = 0; i < keys.length; i++) {
            if (i > 0) blockJson.append(',');
            BlockPos pos = BlockPos.of(keys[i]);
            blockJson.append('[').append(pos.getX()).append(',').append(pos.getY()).append(',')
                    .append(pos.getZ()).append(',').append(Block.getId(level.blocks.get(keys[i]))).append(']');
        }
        blockJson.append(']');
        // 三头牛分处三个 16³ 实体段；用同一种生物避免类序遍历的差。
        double[][] at = {{0.5, 64.0, 0.5}, {1.5, 64.0, 0.5}, {17.5, 64.0, 0.5}, {18.5, 64.0, 0.5}};
        StringBuilder mobs = new StringBuilder("[");
        for (int i = 0; i < at.length; i++) {
            if (i > 0) mobs.append(',');
            Cow cow = EntityTypes.COW.create(level, EntitySpawnReason.COMMAND);
            cow.setUUID(new UUID(0L, i + 1));
            cow.setId(FIRST_ID + i);
            setRandom(cow, 900L + i);
            cow.snapTo(at[i][0], at[i][1], at[i][2], 0.0F, 0.0F);
            cow.setNoAi(true);
            level.tracked.add(cow);
            mobs.append('[').append(Double.doubleToRawLongBits(at[i][0])).append(',')
                    .append(Double.doubleToRawLongBits(at[i][1])).append(',')
                    .append(Double.doubleToRawLongBits(at[i][2])).append(",0,")
                    .append(900L + i).append(",0]");
        }
        mobs.append(']');
        // `findLightningTargetAround` 是 protected，用反射调。 rolled 是 chunk (0,0) 的一格。
        Method find = ServerLevel.class.getDeclaredMethod("findLightningTargetAround", BlockPos.class);
        find.setAccessible(true);
        BlockPos rolled = new BlockPos(8, 64, 0);
        BlockPos target = (BlockPos) find.invoke(level, rolled);
        int candidates = 0;
        for (double[] one : at) {
            if (Math.abs(one[0] - 8.5) <= 4.0 && Math.abs(one[2] - 0.5) <= 4.0) candidates++;
        }
        out.write("{\"type\":\"thunderTarget\",\"name\":\"thunder_target_sections\""
                + ",\"firstId\":" + FIRST_ID + ",\"seed\":1,\"rolled\":[8,64,0]"
                + ",\"blocks\":" + blockJson + ",\"mobs\":" + mobs
                + ",\"target\":[" + target.getX() + "," + target.getY() + "," + target.getZ() + "]"
                + ",\"randomSeed\":" + levelSeed(level) + ",\"candidates\":" + candidates + "}\n");
        return 1;
    }

    /** `thunderHit`：苦力怕带电、海龟掉碗、牛着火受伤。 */
    private static int playThunderHit(Official official, Writer out, String only) throws Exception {
        int cases = 0;
        List<String> names = List.of("thunder_hit_creeper", "thunder_hit_turtle", "thunder_hit_cow");
        for (String name : names) {
            if (only != null && !name.startsWith(only)) continue;
            FakeLevel level = FakeLevel.create(official);
            // 简单难度不跑 `spawnFire`：火只来自 `thunderHit`，逐刻数值才干净。
            ((TickingLevelData) level.levelData).difficulty = Difficulty.EASY;
            level.nextId = FIRST_ID;
            level.entitySeeds = RandomSource.create(ENTITY_RANDOM_SEED);
            level.spawned = new ArrayList<>();
            level.tracked = new ArrayList<>();
            level.injectedCanSeeSky = false;
            level.getRandom().setSeed(1L);
            official.server.sequences = new RandomSequences();
            for (int x = -4; x <= 4; x++) {
                for (int z = -4; z <= 4; z++) {
                    level.blocks.put(BlockPos.asLong(x, 63, z), Blocks.GRASS_BLOCK.defaultBlockState());
                }
            }
            long[] keys = level.blocks.keySet().toLongArray();
            Arrays.sort(keys);
            StringBuilder blockJson = new StringBuilder("[");
            for (int i = 0; i < keys.length; i++) {
                if (i > 0) blockJson.append(',');
                BlockPos pos = BlockPos.of(keys[i]);
                blockJson.append('[').append(pos.getX()).append(',').append(pos.getY()).append(',')
                        .append(pos.getZ()).append(',').append(Block.getId(level.blocks.get(keys[i]))).append(']');
            }
            blockJson.append(']');
            Mob victim = switch (name) {
                case "thunder_hit_creeper" -> new net.minecraft.world.entity.monster.Creeper(EntityTypes.CREEPER, level);
                case "thunder_hit_turtle" -> EntityTypes.TURTLE.create(level, EntitySpawnReason.COMMAND);
                default -> EntityTypes.COW.create(level, EntitySpawnReason.COMMAND);
            };
            victim.setUUID(new UUID(0L, 1L));
            victim.setId(FIRST_ID);
            setRandom(victim, 7L);
            victim.snapTo(0.5, 64.0, 0.5, 0.0F, 0.0F);
            victim.setNoAi(true);
            level.tracked.add(victim);
            net.minecraft.world.entity.LightningBolt bolt =
                    EntityTypes.LIGHTNING_BOLT.create(level, EntitySpawnReason.EVENT);
            bolt.setVisualOnly(false);
            bolt.snapTo(0.5, 64.0, 0.5);
            bolt.setId(FIRST_ID + 1);
            setRandom(bolt, 7L);
            putInt(net.minecraft.world.entity.LightningBolt.class, bolt, "flashes", 0);
            putInt(net.minecraft.world.entity.LightningBolt.class, bolt, "life", 2);
            level.tracked.add(bolt);
            StringBuilder frames = new StringBuilder("[");
            for (int tick = 0; tick <= 6; tick++) {
                if (tick > 0) {
                    for (Entity entity : new ArrayList<>(level.tracked)) {
                        if (entity.isRemoved()) continue;
                        entity.commonTick();
                        entity.tick();
                    }
                }
                if (tick > 0) frames.append(',');
                boolean powered = false;
                int radius = 0;
                if (victim instanceof net.minecraft.world.entity.monster.Creeper creeper) {
                    powered = creeper.isPowered();
                    radius = getInt(net.minecraft.world.entity.monster.Creeper.class, creeper, "explosionRadius");
                }
                int bowls = 0;
                for (Entity e : level.spawned) {
                    if (e instanceof net.minecraft.world.entity.item.ItemEntity item
                            && item.getItem().is(net.minecraft.world.item.Items.BOWL)) {
                        bowls += item.getItem().getCount();
                    }
                }
                frames.append('[').append(Float.floatToRawIntBits(victim.getHealth())).append(',')
                        .append(victim.getRemainingFireTicks()).append(',')
                        .append(powered ? 1 : 0).append(',').append(radius).append(',')
                        .append(bowls * net.minecraft.core.registries.BuiltInRegistries.ITEM.getId(
                                net.minecraft.world.item.Items.BOWL)).append(',')
                        .append(levelSeed(level)).append(']');
            }
            frames.append(']');
            out.write("{\"type\":\"thunderHit\",\"name\":" + jsonString(name)
                    + ",\"firstId\":" + FIRST_ID + ",\"seed\":7,\"start\":[0.5,64.0,0.5]"
                    + ",\"blocks\":" + blockJson + ",\"frames\":" + frames + "}\n");
            cases++;
        }
        return cases;
    }

    /**
     * 嘎枝 / 嘎枝之心：逐刻比心的昼夜状态、绑定的嘎枝、被看着冻结、受伤放树脂和
     * 心被破坏后的拆解死亡。和 {@code bee_full} 一样走真实环境属性时间线，夜里
     * {@code creaking_active} 为真。
     */
    private static void playCreaking(Official official, Writer out, String name) throws Exception {
        FakeLevel level = FakeLevel.create(official);
        try {
            playCreakingInner(official, level, out, name);
        } finally {
            official.attributes = EnvironmentAttributeSystem.builder().addStaticLayers(level).build();
        }
    }

    private static void playCreakingInner(Official official, FakeLevel level, Writer out, String name)
            throws Exception {
        ((TickingLevelData) level.levelData).difficulty = Difficulty.NORMAL;
        level.nextId = FIRST_ID;
        level.gameTime = START_TIME;
        level.injectedCanSeeSky = true;
        level.clock = 12600L;

        int ticks = switch (name) {
            case "creaking_night" -> 40;
            case "creaking_heart_broken" -> 55;
            case "creaking_chase" -> 60;
            case "creaking_heart_removed" -> 30;
            default -> 20;
        };

        // 石地板 y=60，心在 (0,64,0)，两头各一根同轴苍白橡木原木。
        BlockState stone = Blocks.STONE.defaultBlockState();
        for (int x = -16; x <= 16; x++) {
            for (int z = -16; z <= 16; z++) {
                level.blocks.put(BlockPos.asLong(x, 60, z), stone);
            }
        }
        BlockPos heartPos = new BlockPos(0, 64, 0);
        BlockState heartState = Blocks.CREAKING_HEART.defaultBlockState()
                .setValue(net.minecraft.world.level.block.CreakingHeartBlock.AXIS, Direction.Axis.Y)
                .setValue(net.minecraft.world.level.block.CreakingHeartBlock.STATE,
                        net.minecraft.world.level.block.state.properties.CreakingHeartState.DORMANT);
        level.blocks.put(heartPos.asLong(), heartState);
        BlockState log = Blocks.PALE_OAK_LOG.defaultBlockState()
                .setValue(net.minecraft.world.level.block.CreakingHeartBlock.AXIS, Direction.Axis.Y);
        level.blocks.put(heartPos.above().asLong(), log);
        level.blocks.put(heartPos.below().asLong(), log);
        var heartBe = new net.minecraft.world.level.block.entity.CreakingHeartBlockEntity(heartPos, heartState);
        level.putBlockEntity(heartBe);

        // 环境属性：day 时间线的 `creaking_active` 在夜里为真。
        EnvironmentAttributeSystem.Builder builder = EnvironmentAttributeSystem.builder().addStaticLayers(level);
        net.minecraft.world.clock.ClockManager clocks = clock -> new net.minecraft.world.clock.ClockInstance() {
            public long totalTicks() { return level.clock; }
            public float partialTick() { return 0.0F; }
            public float rate() { return 1.0F; }
            public boolean isPaused() { return false; }
        };
        for (Holder<net.minecraft.world.timeline.Timeline> timeline : level.dimensionType().timelines()) {
            builder.addTimelineLayer(timeline, clocks);
        }
        net.minecraft.world.attribute.WeatherAttributes.addBuiltinLayers(builder,
                net.minecraft.world.attribute.WeatherAttributes.WeatherAccess.from(level));
        official.attributes = builder.build();
        put(ServerLevel.class, level, "environmentAttributes", official.attributes);
        level.getRandom().setSeed(1L);
        put(Level.class, level, "soundSeedGenerator", RandomSource.create(12345L));

        // 玩家站在 (4.5, 61, 0.5)，盯着负 X 方向的嘎枝（yaw 90 = -X）。
        ServerPlayer player = new ServerPlayer(official.server, level,
                new GameProfile(new UUID(1L, 2L), "CreakingWatcher"),
                ClientInformation.createDefault());
        player.setPos(name.equals("creaking_chase") ? 6.5 : 4.5, 61.0, 0.5);
        setRandom(player, 0x0DDB1A5E5BAD5EEDL);
        player.setYRot(0.0F);
        player.setYHeadRot(0.0F);
        player.setYBodyRot(0.0F);
        player.setGameMode(GameType.SURVIVAL);
        player.damageCooldownTime = 0;
        RecordingListener connection = allocate(RecordingListener.class);
        put(ServerGamePacketListenerImpl.class, connection, "player", player);
        put(net.minecraft.server.network.ServerCommonPacketListenerImpl.class,
                connection, "server", official.server);
        put(net.minecraft.server.network.ServerCommonPacketListenerImpl.class,
                connection, "connection", new Connection(PacketFlow.CLIENTBOUND));
        connection.bytes = new Bytes(official.registries);
        put(ServerPlayer.class, player, "connection", connection);
        level.playersList().add(player);
        level.tracked.add(player);

        // 预绑定场景：一只 UUID (0,1) 的嘎枝绑在心上；`creaking_night` 让心自己刷。
        boolean preBound = !name.startsWith("creaking_night");
        Creaking creaking = null;
        if (preBound) {
            creaking = EntityTypes.CREAKING.create(level, EntitySpawnReason.COMMAND);
            creaking.setUUID(new UUID(0L, 1L));
            setRandom(creaking, 0x5EED_5EEDL);
            // 官方构造时两个传感器各取一次 `nextInt(20)`，起始延迟再被夹具定成 1；
            // 闸门洗牌随机源是不带种子的静态源，按同一个种子在两边重设。
            BrainOracle.alignCreakingBrain(creaking);
            creaking.snapTo(3.5, 61.0, 0.5, 0.0F, 0.0F);
            creaking.setYHeadRot(0.0F);
            creaking.setYBodyRot(0.0F);
            creaking.setTransient(heartPos);
            heartBe.setCreakingInfo(new UUID(0L, 1L));
            level.tracked.add(creaking);
        }

        // 反射拿 Creaking 的三个布尔元数据 accessor、挥击动画刻数和心的 creakingInfo。
        // `attackAnimationRemainingTicks` 反映每次 `doHurtTarget` 的挥击（冷却 40 刻），
        // 用来确认攻击冷却真的被逐刻对拍覆盖（改坏成 1 会立刻报不一致）。
        Field attackAnimF = net.minecraft.world.entity.monster.creaking.Creaking.class
                .getDeclaredField("attackAnimationRemainingTicks");
        attackAnimF.setAccessible(true);
        Field canMoveF = net.minecraft.world.entity.monster.creaking.Creaking.class.getDeclaredField("CAN_MOVE");
        canMoveF.setAccessible(true);
        var CAN_MOVE = (net.minecraft.network.syncher.EntityDataAccessor<Boolean>) canMoveF.get(null);
        Field activeF = net.minecraft.world.entity.monster.creaking.Creaking.class.getDeclaredField("IS_ACTIVE");
        activeF.setAccessible(true);
        var IS_ACTIVE = (net.minecraft.network.syncher.EntityDataAccessor<Boolean>) activeF.get(null);
        Field tearingF = net.minecraft.world.entity.monster.creaking.Creaking.class.getDeclaredField("IS_TEARING_DOWN");
        tearingF.setAccessible(true);
        var IS_TEARING_DOWN = (net.minecraft.network.syncher.EntityDataAccessor<Boolean>) tearingF.get(null);
        Field infoF = net.minecraft.world.level.block.entity.CreakingHeartBlockEntity.class
                .getDeclaredField("creakingInfo");
        infoF.setAccessible(true);

        String initialBlocks = blockArray(level.blocks);
        StringBuilder frames = new StringBuilder("[");
        for (int tick = 0; tick <= ticks; tick++) {
            if (tick != 0) {
                level.gameTime = START_TIME + tick;
                level.clock = 12600L;
                // `creaking_chase`：前几刻看着（激活 + 冻结），中段转头（追击 + 攻击），
                // 末段再转回来看（验证「玩家转头看它时停住」）。
                boolean watch = name.equals("creaking_watched")
                        || (name.equals("creaking_chase") && (tick < 5 || tick >= 45));
                player.setYRot(watch ? 90.0F : -90.0F);
                player.setXRot(0.0F);
                player.setYHeadRot(watch ? 90.0F : -90.0F);
                if (name.equals("creaking_night")) {
                    // 夜里刷出的嘎枝落点随机，让玩家抬头避免正好对视。
                    player.setYRot(0.0F);
                    player.setXRot(-90.0F);
                    player.setYHeadRot(0.0F);
                }
                level.spawned.clear();
                // 先实体，后方块实体（`ServerLevel.tick` 顺序）。
                if (creaking != null && !creaking.isRemoved()) {
                    creaking.checkDespawn();
                    creaking.commonTick();
                    creaking.tick();
                }
                if (level.getBlockState(heartPos).is(Blocks.CREAKING_HEART)) {
                    net.minecraft.world.level.block.entity.CreakingHeartBlockEntity.serverTick(
                            level, heartPos, level.getBlockState(heartPos), heartBe);
                }
                if (name.equals("creaking_hurt") && tick == 5 && creaking != null) {
                    creaking.hurtServer(level, level.damageSources().playerAttack(player), 3.0F);
                }
                if (name.equals("creaking_heart_broken") && tick == 3) {
                    heartBe.removeProtector(level.damageSources().playerAttack(player));
                    level.removeBlock(heartPos, false);
                }
                if (name.equals("creaking_heart_removed") && tick == 3) {
                    // 心被活塞 / 爆炸这类非玩家方式移走：`preRemoveSideEffects → removeProtector(null)`。
                    heartBe.removeProtector(null);
                    level.removeBlock(heartPos, false);
                }
                // 夜里心刷出来的嘎枝这一刻接进名单，之后逐刻跟着 tick。
                if (creaking == null) {
                    for (Entity entity : level.spawned) {
                        if (entity instanceof net.minecraft.world.entity.monster.creaking.Creaking found
                                && !found.isRemoved()) {
                            creaking = found;
                            // 夜里心自己刷出来的那只也用同一套场景初值。
                            setRandom(creaking, 0x5EED_5EEDL);
                            BrainOracle.alignCreakingBrain(creaking);
                            level.tracked.add(creaking);
                            break;
                        }
                    }
                }
            }
            BlockState hs = level.getBlockState(heartPos);
            String heartStateName = hs.is(Blocks.CREAKING_HEART)
                    ? ((net.minecraft.world.level.block.state.properties.CreakingHeartState)
                            hs.getValue(net.minecraft.world.level.block.CreakingHeartBlock.STATE)).getSerializedName()
                    : "air";
            boolean bound = infoF.get(heartBe) != null;
            boolean present = creaking != null && !creaking.isRemoved();
            boolean canMove = present && creaking.getEntityData().get(CAN_MOVE);
            boolean active = present && creaking.getEntityData().get(IS_ACTIVE);
            boolean tearing = present && creaking.getEntityData().get(IS_TEARING_DOWN);
            int attackAnim = present ? attackAnimF.getInt(creaking) : 0;
            long xBits = present ? Double.doubleToRawLongBits(creaking.getX()) : 0L;
            long zBits = present ? Double.doubleToRawLongBits(creaking.getZ()) : 0L;
            int resin = 0;
            for (int x = -6; x <= 6; x++) {
                for (int y = 58; y <= 66; y++) {
                    for (int z = -6; z <= 6; z++) {
                        if (level.getBlockState(new BlockPos(x, y, z)).is(Blocks.RESIN_CLUMP)) {
                            resin++;
                        }
                    }
                }
            }
            if (tick > 0) frames.append(',');
            // 位置、生命、动画和所有离散字段都逐刻原始位严格相等，没有任何放宽窗口。
            // 生命下降证明「嘎枝从 3 格外走进近战范围并攻击」；挥击动画刻数证明攻击
            // 冷却（40 刻）真的在对拍里——改坏成 1 会每刻挥击、动画常驻 15。玩家不 tick，
            // 首次命中后进入永久无敌，生命只在命中那一刻 20→17 一次。
            frames.append("{\"heartState\":\"").append(heartStateName)
                    .append("\",\"bound\":").append(bound)
                    .append(",\"creakingPresent\":").append(present)
                    .append(",\"canMove\":").append(canMove)
                    .append(",\"active\":").append(active)
                    .append(",\"tearingDown\":").append(tearing)
                    .append(",\"resin\":").append(resin)
                    .append(",\"playerHealth\":")
                    .append(Float.floatToRawIntBits(player.getHealth()))
                    .append(",\"attackAnimation\":").append(attackAnim)
                    .append(",\"x\":").append(xBits)
                    .append(",\"z\":").append(zBits)
                    .append('}');
        }
        frames.append(']');
        out.write("{\"type\":\"creaking\",\"name\":" + jsonString(name)
                + ",\"firstId\":" + FIRST_ID + ",\"blocks\":" + initialBlocks
                + ",\"frames\":" + frames + "}\n");
    }

    private static final class Official {
        final RegistryAccess registries;
        final Holder<DimensionType> overworld;
        final Holder<Biome> plains;
        final DamageSources damageSources;
        final FakeServer server;
        final GameRules gameRules = new GameRules(FeatureFlags.DEFAULT_FLAGS);
        final net.minecraft.world.level.border.WorldBorder border = new net.minecraft.world.level.border.WorldBorder();
        EnvironmentAttributeSystem attributes;

        private Official(ReloadableServerResources managers) {
            this.registries = (RegistryAccess) managers.fullRegistries().lookup();
            this.overworld = registries.lookupOrThrow(Registries.DIMENSION_TYPE).getOrThrow(BuiltinDimensionTypes.OVERWORLD);
            this.plains = registries.lookupOrThrow(Registries.BIOME).getOrThrow(Biomes.PLAINS);
            this.damageSources = new DamageSources(registries);
            this.server = FakeServer.create(managers, gameRules);
        }

        static Official load(CloseableResourceManager resources) throws Exception {
            var initial = RegistryLayer.createRegistryAccess();
            List<Registry.PendingTags<?>> staticTags =
                    TagLoader.loadTagsForExistingRegistries(resources, initial.getLayer(RegistryLayer.STATIC));
            RegistryAccess.Frozen context = initial.getAccessForLoading(RegistryLayer.WORLD);
            List<HolderLookup.RegistryLookup<?>> lookups = TagLoader.buildUpdatedLookups(context, staticTags);
            RegistryAccess.Frozen world = RegistryDataLoader.load(
                            resources, lookups, RegistryDataLoader.WORLD_REGISTRIES, ForkJoinPool.commonPool())
                    .join();
            var layers = initial.replaceFrom(RegistryLayer.WORLD, world);
            ReloadableServerResources managers = ReloadableServerResources.loadResources(
                            resources,
                            layers,
                            staticTags,
                            FeatureFlags.DEFAULT_FLAGS,
                            net.minecraft.commands.Commands.CommandSelection.DEDICATED,
                            LevelBasedPermissionSet.GAMEMASTER,
                            ForkJoinPool.commonPool(),
                            Runnable::run)
                    .get();
            managers.updateComponentsAndStaticRegistryTags();
            managers.getRecipeManager().finalizeRecipeLoading(FeatureFlags.DEFAULT_FLAGS);
            Official official = new Official(managers);
            FakeLevel sample = FakeLevel.create(official);
            official.attributes = EnvironmentAttributeSystem.builder().addStaticLayers(sample).build();
            return official;
        }
    }

    private static final class FakeServer extends DedicatedServer {
        private ReloadableServerResources managers;
        private GameRules rules;
        /** `MinecraftServer.getLevel` 的假世界表。 */
        public java.util.Map<ResourceKey<Level>, ServerLevel> levels = java.util.Map.of();
        /** 战利品表的随机序列，世界种子和 Bamboo 的缺省一样是 0。 */
        private RandomSequences sequences = new RandomSequences();
        /** 1c：`WorldData.getGameType()`（冒险模式走 findSpawn 的 fixup 分支）。 */
        GameType spawnGameType = GameType.CREATIVE;

        private FakeServer() {
            super(null, null, null, null, null, null, null, null, null, null);
        }

        static FakeServer create(ReloadableServerResources managers, GameRules rules) {
            FakeServer server = allocate(FakeServer.class);
            server.managers = managers;
            server.rules = rules;
            server.sequences = new RandomSequences();
            return server;
        }

        @Override
        public net.minecraft.world.item.crafting.RecipeManager getRecipeManager() {
            return managers.getRecipeManager();
        }

        @Override
        public ReloadableServerRegistries.Holder reloadableRegistries() {
            // 死亡场景要跑真的 `minecraft:entities/cow` 战利品表。
            // Death scenes need the real `minecraft:entities/cow` loot table.
            return managers.fullRegistries();
        }

        @Override
        public RandomSource getRandomSequence(Identifier key) {
            return sequences.get(key, 0L);
        }

        @Override
        public GameRules getGameRules() {
            return rules;
        }

        @Override
        public net.minecraft.world.level.storage.WorldData getWorldData() {
            // `PlayerSpawnFinder.findSpawn` 只读 `getGameType()`；用接口代理
            // 给一个最小实现，不构造真正的 WorldData。
            return (net.minecraft.world.level.storage.WorldData) java.lang.reflect.Proxy.newProxyInstance(
                    net.minecraft.world.level.storage.WorldData.class.getClassLoader(),
                    new Class<?>[] {net.minecraft.world.level.storage.WorldData.class},
                    (proxy, method, args) -> {
                        if (method.getName().equals("getGameType")) return spawnGameType;
                        if (method.getName().equals("isFlatWorld")) return true;
                        Class<?> type = method.getReturnType();
                        if (type == boolean.class) return false;
                        if (type == int.class) return 0;
                        if (type == long.class) return 0L;
                        return null;
                    });
        }

        @Override
        public ServerLevel getLevel(ResourceKey<Level> key) {
            return levels == null ? null : levels.get(key);
        }

        @Override
        public net.minecraft.world.clock.ServerClockManager clockManager() {
            net.minecraft.world.clock.ServerClockManager mgr = allocate(net.minecraft.world.clock.ServerClockManager.class);
            net.minecraft.world.clock.ServerClockManager.ServerClockInstance inst =
                    new net.minecraft.world.clock.ServerClockManager.ServerClockInstance() {
                        @Override
                        public long totalTicks() {
                            ServerLevel lvl = FakeServer.this.getLevel(Level.OVERWORLD);
                            return (lvl instanceof FakeLevel fake) ? fake.clock : 0L;
                        }
                    };
            java.util.Map<Object, Object> map = new java.util.AbstractMap<>() {
                @Override
                public Object get(Object key) {
                    return inst;
                }
                @Override
                public java.util.Set<Entry<Object, Object>> entrySet() {
                    return java.util.Set.of();
                }
            };
            put(net.minecraft.world.clock.ServerClockManager.class, mgr, "clocks", map);
            return mgr;
        }

        @Override
        public net.minecraft.server.permissions.LevelBasedPermissionSet getProfilePermissions(
                net.minecraft.server.players.NameAndId name) {
            return net.minecraft.server.permissions.LevelBasedPermissionSet.GAMEMASTER;
        }

        @Override
        public void sendSystemMessage(Component message) {}

        @Override
        public void managedBlock(java.util.function.BooleanSupplier condition) {
            while (!condition.getAsBoolean()) {
                // 假世界的 chunk future 已经完成，轮询任务队列即可。
                if (!this.pollTaskForSpawn()) break;
            }
        }

        @Override
        public void execute(Runnable task) {
            task.run();
        }

        @Override
        public void executeIfPossible(Runnable task) {
            task.run();
        }

        private boolean pollTaskForSpawn() {
            try {
                java.lang.reflect.Method poll = net.minecraft.util.thread.BlockableEventLoop.class
                        .getDeclaredMethod("pollTask");
                poll.setAccessible(true);
                return (Boolean) poll.invoke(this);
            } catch (ReflectiveOperationException error) {
                throw new IllegalStateException(error);
            }
        }

        @Override
        public boolean allowFlight() {
            return false;
        }

        @Override
        public GameType getDefaultGameType() {
            return GameType.SURVIVAL;
        }

        @Override
        public GameType getForcedGameType() {
            return null;
        }

        @Override
        public boolean forceGameMode() {
            return false;
        }

        @Override
        public net.minecraft.util.debug.ServerDebugSubscribers debugSubscribers() {
            return new net.minecraft.util.debug.ServerDebugSubscribers(this);
        }
    }

