    /** 区块缓存：寻路和地面搜索走 {@code getChunkNow}，交给假世界的区块表。 */
    private static final class Chunks extends ServerChunkCache {
        FakeLevel level;
        ChunkGenerator naturalGenerator;
        /** 实体事件和音效走这里，和同步包一起记进同一刻的字节流。 */
        java.util.function.Consumer<Packet<? super ClientGamePacketListener>> events;

        private Chunks() {
            super(null, null, null, null, null, null, 0, 0, false, null);
        }

        @Override
        public ChunkGenerator getGenerator() {
            return naturalGenerator == null ? super.getGenerator() : naturalGenerator;
        }

        @Override
        public LevelChunk getChunkNow(int chunkX, int chunkZ) {
            return (LevelChunk) level.getChunk(chunkX, chunkZ, ChunkStatus.FULL, false);
        }

        /** 蜜蜂找巢要用 `PoiManager`：临时目录里建一个空的官方实例。 */
        private net.minecraft.world.entity.ai.village.poi.PoiManager poiManager;

        @Override
        public net.minecraft.world.entity.ai.village.poi.PoiManager getPoiManager() {
            if (level.realPoi != null) {
                return level.realPoi;
            }
            if (poiManager == null) {
                try {
                    var dir = java.nio.file.Files.createTempDirectory("bamboo-bee-poi-");
                    poiManager = new net.minecraft.world.entity.ai.village.poi.PoiManager(
                            new net.minecraft.world.level.chunk.storage.RegionStorageInfo(
                                    "bee-oracle", net.minecraft.world.level.Level.OVERWORLD, "poi"),
                            dir,
                            net.minecraft.util.datafix.DataFixers.getDataFixer(),
                            false,
                            level.official.registries,
                            new net.minecraft.world.level.chunk.storage.ChunkIOErrorReporter() {
                                @Override public void reportChunkLoadFailure(Throwable error,
                                        net.minecraft.world.level.chunk.storage.RegionStorageInfo info,
                                        net.minecraft.world.level.ChunkPos pos) {}
                                @Override public void reportChunkSaveFailure(Throwable error,
                                        net.minecraft.world.level.chunk.storage.RegionStorageInfo info,
                                        net.minecraft.world.level.ChunkPos pos) {}
                            },
                            level);
                } catch (Exception error) {
                    throw new IllegalStateException(error);
                }
            }
            return poiManager;
        }

        @Override
        public CompletableFuture<?> addTicketAndLoadWithRadius(
                TicketType type, ChunkPos pos, int radius) {
            // 假世界所有区块都在内存里，官方的加载 future 立刻完成。
            return CompletableFuture.completedFuture(null);
        }

        @Override
        public void move(ServerPlayer player) {}

        @Override
        public void sendToTrackingPlayersAndSelf(Entity entity,
                Packet<? super ClientGamePacketListener> packet) {
            if (events != null) {
                events.accept(packet);
            }
        }

        @Override
        public void sendToTrackingPlayers(Entity entity,
                Packet<? super ClientGamePacketListener> packet) {
            if (events != null) {
                events.accept(packet);
            }
            if (level.mobPackets != null && entity instanceof Mob) {
                level.mobPackets.accept(packet);
            }
        }
    }

