        @Override
        public boolean addFreshEntity(Entity entity) {
            // `EntityType.spawn` 在加入世界之后才叫 `playAmbientSound`。官方实体的
            // 随机源不带种子，这里换成 Bamboo 的种子源并只重放构造时的三个数，
            // 这样那一声的音高也是确定的（其余场景的牛仍由场景显式给种子）。
            // `EntityType.spawn` plays the ambient sound after adding the entity.
            // Vanilla's entity random is unseeded; replace it with Bamboo's seed
            // source and replay only the constructor draws so the pitch is fixed.
            if (eggSeed != null) {
                setRandom(entity, eggSeed);
                RandomSource random = entity.getRandom();
                entity.setUUID(Mth.createInsecureUUID(random));
                random.nextFloat();
                eggSeed = null;
            }
            if (entity instanceof Animal calf && dropUuids) {
                newbornCows.add(calf);
            }
            // 生成期区域查不到实体（`WorldGenRegion.getEntities` 恒空），不进 tracked。
            // A world-generation region sees no entities, so keep them out of tracked.
            if (naturalScene != null && !worldGenRegion) {
                tracked.add(entity);
            }
            if (spawnerScene) {
                tracked.add(entity);
            }
            spawned.add(entity);
            return true;
        }

        @Override
        public boolean addWithUUID(net.minecraft.world.entity.Entity entity) {
            // 官方 `ServerPlayer.respawnEntityOnShoulder` 走 addWithUUID；假世界没有
            // entityManager，接到 addFreshEntity 收集实体即可，避免空指针。
            // Vanilla's respawnEntityOnShoulder calls addWithUUID; the fake world has
            // no entityManager, so route it to addFreshEntity.
            return addFreshEntity(entity);
        }

        /** 按幼崽 / 掉落物的构造顺序给新实体换上岛的种子源，并重放构造取数。 */
        /** 假世界的玩家没有连接，粒子包不发（哞菇喂花 / 剪毛会走到这里）。 */
        @Override
        public <T extends net.minecraft.core.particles.ParticleOptions> int sendParticles(T particle,
                boolean overrideLimiter, boolean alwaysShow, double x, double y, double z, int count,
                double xDist, double yDist, double zDist, double xSpeed, double ySpeed, double zSpeed,
                net.minecraft.network.protocol.game.ClientboundLevelParticlesPacket.RandomizationType type) {
            return 0;
        }

        void reseedBorn(Entity entity) {
            if (!dropUuids) {
                return;
            }
            if (entity instanceof Animal calf) {
                long seed = entitySeeds.nextLong();
                BORN_SEEDS.put(calf.getId(), seed);
                setRandom(calf, seed);
                RandomSource random = calf.getRandom();
                calf.setUUID(Mth.createInsecureUUID(random));
                random.nextFloat();
                return;
            }
            if (entity instanceof net.minecraft.world.entity.item.ItemEntity
                    || entity instanceof net.minecraft.world.entity.ExperienceOrb) {
                entity.setUUID(new UUID(0x0000BAAB00000000L, entity.getId()));
                long seed = entitySeeds.nextLong();
                BORN_SEEDS.put(entity.getId(), seed);
                setRandom(entity, seed);
                RandomSource random = entity.getRandom();
                if (entity instanceof net.minecraft.world.entity.item.ItemEntity) {
                    random.nextFloat();
                    entity.setYRot(random.nextFloat() * 360.0F);
                    double dx = random.nextDouble() * 0.2 - 0.1;
                    double dz = random.nextDouble() * 0.2 - 0.1;
                    entity.setDeltaMovement(dx, 0.2, dz);
                } else {
                    entity.setYRot(random.nextFloat() * 360.0F);
                    double dx = (random.nextDouble() * 0.2 - 0.1) * 2.0;
                    double dy = random.nextDouble() * 0.2 * 2.0;
                    double dz = (random.nextDouble() * 0.2 - 0.1) * 2.0;
                    entity.setDeltaMovement(dx, dy, dz);
                }
            }
        }

        /** UUID 和已有实体重复时放不进去，其余放进实体名单。 */
        @Override
        public boolean tryAddFreshEntityWithPassengers(Entity entity) {
            for (Entity existing : tracked) {
                if (existing.getUUID().equals(entity.getUUID())) {
                    return false;
                }
            }
            tracked.add(entity);
            // 刷怪笼对拍：这一轮新加的实体同时进 `spawned`，供逐刻帧记录种类和位置。
            if (spawnerScene) {
                spawned.add(entity);
            }
            return true;
        }

